-- ═════════════════════════════════════════════════════════════════════════════
-- Hand-written below: rules Prisma's schema language cannot express.
-- Covered by apps/api/test/attendance-database.e2e-spec.ts.
-- ═════════════════════════════════════════════════════════════════════════════

-- ── Biometric credentials (§4.5, §16.1) ──────────────────────────────────────
ALTER TABLE "webauthn_credentials"
  ADD CONSTRAINT "webauthn_credentials_values" CHECK (
    btrim("name") <> '' AND "credential_id" ~ '^[A-Za-z0-9_-]+$' AND "sign_count" >= 0 AND
    ("revoked_at" IS NOT NULL OR "revoke_reason" IS NULL));

-- A credential belongs to the account that enrolled it, forever: owner, id and
-- key never change, and a revoked credential is never reinstated.
CREATE FUNCTION "ftms_check_credential_update"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."user_id" <> OLD."user_id" OR NEW."credential_id" <> OLD."credential_id"
     OR NEW."public_key" <> OLD."public_key" OR NEW."created_at" <> OLD."created_at" THEN
    RAISE EXCEPTION 'credential % belongs to the account that enrolled it', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."revoked_at" IS NOT NULL AND NEW."revoked_at" IS DISTINCT FROM OLD."revoked_at" THEN
    RAISE EXCEPTION 'credential % has been revoked', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "webauthn_credentials_immutable"
  BEFORE UPDATE ON "webauthn_credentials"
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_credential_update"();

-- ── Challenges: registration and check-in are tied to an account; check-in to a visit ──
ALTER TABLE "webauthn_challenges"
  ADD CONSTRAINT "webauthn_challenges_binding" CHECK (
    ("purpose" = 'CHECK_IN') = ("visit_id" IS NOT NULL) AND
    ("purpose" = 'AUTHENTICATION' OR "user_id" IS NOT NULL) AND
    "expires_at" > "created_at");

-- ── Attendance records (§8, §16.1) ───────────────────────────────────────────
ALTER TABLE "attendance_records"
  ADD CONSTRAINT "attendance_records_lateness" CHECK (
    ("status" = 'LATE') = ("minutes_late" > 0) AND "minutes_late" BETWEEN 0 AND 720);
ALTER TABLE "attendance_records"
  ADD CONSTRAINT "attendance_records_source" CHECK (
    ("source" <> 'QR' OR "checked_in_at" IS NOT NULL) AND
    ("source" <> 'MANUAL' OR "corrected_at" IS NOT NULL) AND
    ("source" <> 'AUTOMATIC' OR ("status" = 'ABSENT' AND "checked_in_at" IS NULL)) AND
    ("biometric_verified" = false OR "checked_in_at" IS NOT NULL));
ALTER TABLE "attendance_records"
  ADD CONSTRAINT "attendance_records_location" CHECK (
    ("latitude" IS NULL) = ("longitude" IS NULL) AND
    ("latitude" IS NULL OR ("latitude" BETWEEN -90 AND 90 AND "longitude" BETWEEN -180 AND 180)) AND
    ("accuracy_meters" IS NULL OR ("latitude" IS NOT NULL AND "accuracy_meters" >= 0)) AND
    ("distance_meters" IS NULL OR ("latitude" IS NOT NULL AND "distance_meters" >= 0)));
ALTER TABLE "attendance_records"
  ADD CONSTRAINT "attendance_records_correction" CHECK (
    ("corrected_at" IS NOT NULL OR ("corrected_by_id" IS NULL AND "correction_reason" IS NULL)));

-- New records only for visits that take place, and only under one of the
-- visit's groups ("valid group assignments for attendance"). The record's
-- visit, student and group never change; corrections change its status.
CREATE FUNCTION "ftms_check_attendance"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  visit_status "VisitStatus";
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW."visit_id" <> OLD."visit_id" OR NEW."student_id" <> OLD."student_id"
       OR NEW."group_id" <> OLD."group_id" OR NEW."created_at" <> OLD."created_at" THEN
      RAISE EXCEPTION 'attendance record % cannot be moved to another visit, student or group', OLD."id"
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  SELECT "status" INTO visit_status FROM "training_visits" WHERE "id" = NEW."visit_id" FOR SHARE;
  IF visit_status IS DISTINCT FROM 'SCHEDULED' THEN
    RAISE EXCEPTION 'visit % is cancelled: attendance cannot be registered', NEW."visit_id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "visit_groups" WHERE "visit_id" = NEW."visit_id" AND "group_id" = NEW."group_id") THEN
    RAISE EXCEPTION 'group % is not assigned to visit %', NEW."group_id", NEW."visit_id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "attendance_records_check"
  BEFORE INSERT OR UPDATE ON "attendance_records"
  FOR EACH ROW EXECUTE FUNCTION "ftms_check_attendance"();

CREATE INDEX "training_visits_absences_due" ON "training_visits" ("starts_at")
  WHERE "status" = 'SCHEDULED' AND "absences_processed_at" IS NULL;

-- ── Row Level Security (Supabase Data API gets nothing; see Phase 1) ────────
ALTER TABLE "webauthn_credentials" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "webauthn_challenges" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "attendance_records" ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE
  api_role TEXT;
BEGIN
  FOREACH api_role IN ARRAY ARRAY['anon', 'authenticated'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = api_role) THEN
      EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA public FROM %I', api_role);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM %I', api_role);
    END IF;
  END LOOP;
END $$;
